const canvas = document.querySelector('#world'), ctx = canvas.getContext('2d');
const W=2200,H=1600, player={x:1100,y:800}, keys=new Set();
const state={seeds:0,petals:0,planted:0,level:1,flowers:[]};
let randomSeed=99; function rand(){randomSeed=(randomSeed*16807)%2147483647;return (randomSeed-1)/2147483646}
for(let i=0;i<125;i++)state.flowers.push({x:55+rand()*(W-110),y:55+rand()*(H-110),type:i%3,alive:true,planted:false});
// A few discoveries close to the starting point.
state.flowers.push({x:1150,y:815,type:0,alive:true},{x:1040,y:750,type:1,alive:true},{x:1100,y:730,type:2,alive:true});
const grasses=Array.from({length:500},()=>({x:rand()*W,y:rand()*H,s:2+rand()*5}));
let toastTimer; function say(message){const el=document.querySelector('#toast');el.textContent=message;clearTimeout(toastTimer);el.style.opacity=1;toastTimer=setTimeout(()=>el.style.opacity=.65,3500)}
function update(){for(const [id,n] of [['seeds',state.seeds],['petals',state.petals],['planted',state.planted]])document.querySelector('#'+id).textContent=String(n).padStart(2,'0');document.querySelector('#level').textContent=`LANTERN LEVEL ${String(state.level).padStart(2,'0')} · REACH ${54+(state.level-1)*20}`}
function gather(){let nearest=null, distance=54+(state.level-1)*20;for(const f of state.flowers){if(!f.alive)continue;const d=Math.hypot(f.x-player.x,f.y-player.y);if(d<distance){distance=d;nearest=f}}if(!nearest){say('Nothing close enough yet. Wander toward a bloom.');return}nearest.alive=false;state.seeds++;state.petals++;say('A glowseed and a petal, gathered gently.');update()}
function plant(){if(!state.seeds){say('Gather a bloom first to find a glowseed.');return}state.seeds--;state.planted++;state.flowers.push({x:player.x+20,y:player.y+22,type:2,alive:true,planted:true});say('A new bloom takes root. Make this place your own.');update()}
document.querySelector('#upgrade').onclick=()=>{if(state.petals<4){say('Gather 4 petals to upgrade your lantern.');return}state.petals-=4;state.level++;say('Your lantern reaches a little further.');update()};
document.querySelector('#reset').onclick=()=>{if(confirm('Start a new grove? Your current progress will be lost.'))location.reload()};
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','w','a','s','d','p'].includes(e.key))e.preventDefault();if(!e.repeat&&e.key===' ')gather();if(!e.repeat&&e.key.toLowerCase()==='p')plant();keys.add(e.key.toLowerCase())});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));addEventListener('blur',()=>keys.clear());
function circle(x,y,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}
function draw(time){let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0),length=Math.hypot(dx,dy)||1;player.x=Math.max(20,Math.min(W-20,player.x+dx/length*2.5));player.y=Math.max(20,Math.min(H-20,player.y+dy/length*2.5));const ox=Math.max(0,Math.min(W-canvas.width,player.x-canvas.width/2)),oy=Math.max(0,Math.min(H-canvas.height,player.y-canvas.height/2));ctx.fillStyle='#89a97e';ctx.fillRect(0,0,1100,580);ctx.save();ctx.translate(-ox,-oy);
// Soft patches give the meadow a painterly, ungridded surface.
for(let i=0;i<30;i++){let x=(i*379)%W,y=(i*619)%H;ctx.fillStyle=i%2?'#789b7080':'#a2b98980';ctx.beginPath();ctx.ellipse(x,y,100+i%4*30,50+i%3*25,i,0,Math.PI*2);ctx.fill()}
for(const g of grasses){ctx.strokeStyle='#527b5b80';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(g.x,g.y);ctx.lineTo(g.x-g.s/2,g.y-g.s);ctx.moveTo(g.x,g.y);ctx.lineTo(g.x+g.s/2,g.y-g.s*.8);ctx.stroke()}
for(const f of state.flowers){if(!f.alive)continue;const pulse=1+Math.sin(time/700+f.x)*.1;ctx.strokeStyle='#547d57';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(f.x,f.y+10);ctx.lineTo(f.x,f.y-3);ctx.stroke();const colors=['#f2dca4','#e9bbb0','#e8edbd'];for(let j=0;j<5;j++){const a=j*Math.PI*2/5;circle(f.x+Math.cos(a)*5*pulse,f.y-5+Math.sin(a)*5*pulse,4,colors[f.type])}circle(f.x,f.y-5,3,'#d9b66e');if(f.planted){ctx.strokeStyle='#f2f4c077';ctx.beginPath();ctx.arc(f.x,f.y-5,14,0,7);ctx.stroke()}}
const glow=ctx.createRadialGradient(player.x,player.y,2,player.x,player.y,70);glow.addColorStop(0,'#f7f7c555');glow.addColorStop(1,'#f7f7c500');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(player.x,player.y,70,0,7);ctx.fill();ctx.fillStyle='#28493a55';ctx.beginPath();ctx.ellipse(player.x,player.y+13,13,5,0,0,7);ctx.fill();circle(player.x,player.y,11,'#f1e6c7');circle(player.x,player.y-5,7,'#f8f1d9');circle(player.x+3,player.y-6,1.5,'#49614b');ctx.restore();document.querySelector('#location').textContent=`MEADOW · ${Math.round((player.x-1100)/10)}, ${Math.round((800-player.y)/10)}`;requestAnimationFrame(draw)}update();requestAnimationFrame(draw);
